        outer(a_outer, b_outer);
    });

    h_outer.join().unwrap();

    println!("DONE done=1");
}

fn outer(a: Arc<Mutex<()>>, b: Arc<Mutex<()>>) {
    let a_x1 = Arc::clone(&a);
    let b_x1 = Arc::clone(&b);
    let a_x2 = Arc::clone(&a);
    let b_x2 = Arc::clone(&b);

    let h_x1 = thread::spawn(move || {
        x1(a_x1, b_x1);
    });
    let h_x2 = thread::spawn(move || {
        x2(a_x2, b_x2);
    });

    h_x1.join().unwrap();
    h_x2.join().unwrap();
