// A bounded channel with capacity 1, built from two semaphores.
struct Channel {
    // Counts available slots (initially 1).
    empty: Arc<Semaphore>,
    // Counts available items (initially 0).
    full: Arc<Semaphore>,
    // The single buffered value.
    slot: Mutex<Option<i32>>,
}

